param([string]$Source="source-private/SEIF-master-v0.1.docx")
$ErrorActionPreference="Stop";$repo=Split-Path -Parent $PSScriptRoot;$sourcePath=Join-Path $repo $Source
if(-not(Test-Path -LiteralPath $sourcePath -PathType Leaf)){throw "SOURCE NOT FOUND"}
Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($sourcePath)
try{$entry=$zip.GetEntry("word/document.xml");$reader=[IO.StreamReader]::new($entry.Open());try{[xml]$document=$reader.ReadToEnd()}finally{$reader.Dispose()}}finally{$zip.Dispose()}
$ns=[Xml.XmlNamespaceManager]::new($document.NameTable);$ns.AddNamespace("w","http://schemas.openxmlformats.org/wordprocessingml/2006/main");$body=$document.SelectSingleNode("//w:body",$ns)
function Text-Of($node){return (($node.SelectNodes(".//w:t",$ns)|ForEach-Object{$_.InnerText})-join"").Trim()}
function Max-Size($p){$s=@($p.SelectNodes(".//w:rPr/w:sz",$ns)|ForEach-Object{[int]$_.GetAttribute("val",$ns.LookupNamespace("w"))});if(!$s.Count){return 0};return ($s|Measure-Object -Maximum).Maximum}
function Slugify([string]$v){$n=$v.Normalize([Text.NormalizationForm]::FormD);$c=$n.ToCharArray()|Where-Object{[Globalization.CharUnicodeInfo]::GetUnicodeCategory($_)-ne[Globalization.UnicodeCategory]::NonSpacingMark};return ((-join$c).ToLowerInvariant()-replace"[^a-z0-9]+","-").Trim("-")}
function Ref([int]$chapter,[string]$locator){$title=if($chapter-eq18){"18. North Star & Metric Tree"}else{"19. Rituales de Gobierno"};return [ordered]@{title=$title;locator=$locator}}
function CV([string]$id,[string]$subject){return [ordered]@{id=$id;subject=$subject;status="CLIENT VALIDATION REQUIRED"}}
function Section-Class([string]$title){if($title-match'(?i)North Star|Target|AI|Maturity'){return "hypothesis"};if($title-match'(?i)assessment|AS-IS|Diagnóstico'){return "mixed"};return "recommendation"}
function Validations-For([int]$chapter,[string]$title){$r=@();if($title-match'(?i)Owner|Role|célula'){$r+=,(CV "CL-04" "Mapeo organizacional de roles fuente")};if($title-match'(?i)Decision|Outcome Review|Quarterly|Escalation|autoridad'){$r+=,(CV "CL-05" "Decision rights y autoridad organizacional")};if($title-match'(?i)North Star'){$r+=,(CV "CL-06" "North Star candidate")};if($title-match'(?i)Metric|Métrica|Target|Dashboard|Instrumentation'){$r+=,(CV "CL-07" "Definiciones operacionales, baseline, targets y ownership")};if($title-match'(?i)TTV|Adoption|Adherence'){$r+=,(CV "CL-08" "Definiciones de Adoption y TTV")};if($title-match'(?i)WIP|prioridad'){$r+=,(CV "CL-09" "Límites numéricos de WIP")};if($title-match'(?i)Jira|Confluence|AI|IA|Dashboard'){$r+=,(CV "CL-10" "Arquitectura futura de tooling")};if($title-match'(?i)Cadence|Ritual|Review|reunión'){$r+=,(CV "CL-11" "Cadencias propuestas")};if($title-match'(?i)Capacity|capacidad|deuda'){$r+=,(CV "CL-12" "Política de capacidad y deuda")};if($title-match'(?i)Growth|Expansion'){$r+=,(CV "CL-13" "Ownership de Growth / Expansion")};if($title-match'(?i)Maturity|madurez'){$maturityId=if($chapter-eq18){"CL-17"}else{"CL-18"};$r+=,(CV $maturityId "Valoración del assessment — madurez pendiente de validación")};return $r}
function Extract-Chapter([int]$target,[int]$next){$result=[ordered]@{sections=@();start=$null;end=$null};$current=0;$expected=1;$pi=0;$ti=0;$script:section=$null;$script:pending=@();$script:pendingStart=$null;$script:pendingEnd=$null
 function Flush{if($null-ne$script:section-and$script:pending.Count){$script:section.blocks+=[ordered]@{type="list";items=@($script:pending);source=(Ref $target "P$script:pendingStart–P$script:pendingEnd")}};$script:pending=@();$script:pendingStart=$null;$script:pendingEnd=$null}
 foreach($node in $body.ChildNodes){if($node.LocalName-eq"p"){$pi++;$text=Text-Of $node;if($expected-le$next-and$text-match("^"+$expected+"\.\s+")-and(Max-Size $node)-ge36){Flush;$current=$expected;$expected++;if($current-eq$target){$result.start="P$pi";$script:section=$null;continue};if($current-eq$next){$result.end="P$($pi-1)";break}};if($current-ne$target){continue};$result.end="P$pi";if(!$text){Flush;continue};if($text-match("^"+$target+"\.\d+\s+")){Flush;$title=($text-replace("^"+$target+"\.\d+\s+"),'').Trim();$script:section=[ordered]@{id=(Slugify $title);title=$title;contentClass=(Section-Class $title);blocks=@();evidence=@();sources=@((Ref $target "P$pi"))};$v=Validations-For $target $title;if($v.Count){$script:section.clientValidations=@($v)};$result.sections+=$script:section;continue};if($null-eq$script:section){continue};$isList=$null-ne$node.SelectSingleNode("./w:pPr/w:numPr",$ns);if($isList){if(!$script:pending.Count){$script:pendingStart=$pi};$script:pendingEnd=$pi;$script:pending+=$text}else{Flush;$script:section.blocks+=[ordered]@{type="paragraph";text=$text;source=(Ref $target "P$pi")}}}elseif($node.LocalName-eq"tbl"){$ti++;if($current-ne$target){continue};Flush;$rows=@();foreach($row in $node.SelectNodes("./w:tr",$ns)){$rows+=,@($row.SelectNodes("./w:tc",$ns)|ForEach-Object{Text-Of $_})};if($rows.Count-and$null-ne$script:section){$headers=@($rows[0]);$data=if($rows.Count-gt1){@($rows[1..($rows.Count-1)])}else{@()};$kind=if(($headers-join" ")-match'(?i)Nivel|Dimensión|Decisión|Cadencia'){"comparison"}elseif(($headers-join" ")-match'(?i)Métrica'){"scorecard"}else{"simple"};$script:section.blocks+=[ordered]@{type="table";table=[ordered]@{id=("source-table-{0:D3}"-f$ti);caption=$script:section.title;kind=$kind;headers=$headers;rows=$data;source=(Ref $target "T$ti")}}}}};Flush;return $result}
function Complete-Metric([string[]]$complete,[string[]]$partial,[string[]]$missing){$v=[ordered]@{};foreach($k in $complete){if($k){$v[$k]="SOURCE COMPLETE"}};foreach($k in $partial){if($k){$v[$k]="SOURCE PARTIAL"}};foreach($k in $missing){if($k){$v[$k]="SOURCE MISSING"}};return $v}
function Metric([string]$id,[string]$name,[string]$family,[string]$definition,[string]$locator,[string]$indicator="UNCLASSIFIED",[string]$formula="SOURCE MISSING",[string]$numerator="SOURCE MISSING",[string]$denominator="SOURCE MISSING",[string]$population="SOURCE MISSING"){$provided=@("WHAT","WHY","DEFINITION","DECISION");if($formula-ne"SOURCE MISSING"){$provided+="FORMULA"};$missing=@("FORMULA","POPULATION","DATA SOURCE","OWNER","CADENCE","BASELINE","TARGET","BUSINESS LINKAGE")|Where-Object{$_-notin$provided};return [ordered]@{id=$id;name=$name;family=$family;purpose="Informar diagnóstico y decisión sin sustituir evidencia de Outcome.";definition=$definition;formula=$formula;numerator=$numerator;denominator=$denominator;population=$population;timeWindow="SOURCE MISSING";dataSource="SOURCE MISSING";owner="SOURCE MISSING";reviewCadence="SOURCE MISSING";baseline="SOURCE MISSING";target="SOURCE MISSING";threshold="SOURCE MISSING";decisionEnabled="Investigar cambio, decidir acción y observar resultado";indicatorType=$indicator;valueClass="PENDING VALIDATION";source=(Ref 18 $locator);validationStatus="pending";completeness=(Complete-Metric $provided @() $missing)}}
function Gov-Complete([bool]$owner,[bool]$escalation){$partial=@("REVISIT CONDITION","TOOL");$missing=@();if($owner){$partial+="DECISION RIGHT"}else{$missing+="DECISION RIGHT"};if($escalation){$partial+="ESCALATION"}else{$missing+="ESCALATION"};return (Complete-Metric @("WHAT","WHY","WHO","WHEN","INPUT","EVIDENCE","OUTPUT","ARTIFACT","METRIC") $partial $missing)}
function Gov([string]$id,[string]$name,[string]$layer,[string]$purpose,[string]$cadence,[bool]$contextual,[string[]]$inputs,[string[]]$evidence,[string[]]$participants,[string[]]$decisions,[string[]]$outputs,[string]$locator,[string]$owner="",[string]$escalation=""){$v=[ordered]@{id=$id;name=$name;layer=$layer;purpose=$purpose;cadence=$cadence;contextual=$contextual;inputs=$inputs;evidenceReviewed=$evidence;participants=$participants;possibleDecisions=$decisions;outputs=$outputs;artifactsUpdated=@("Outcome Board","Decision Log");source=(Ref 19 $locator);validationStatus="pending";completeness=(Gov-Complete ([bool]$owner) ([bool]$escalation))};if($owner){$v.decisionOwner=$owner};if($escalation){$v.escalation=$escalation};return $v}
